'use strict';
const APP='year9-week5-theory',VERSION=2;
const params=new URLSearchParams(location.search),teacher=params.get('teacher')==='1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=x=>String(x||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim().replace(/\s+/g,' ');
const matchesSupport=name=>/(?:^| )ng *jun *kai(?: |$)/u.test(normalize(name));
const prefix=APP+(teacher?'-teacher':'-student');
function fresh(){return {app:APP,version:VERSION,name:'',className:'',lang:'en',compare:false,guided:false,page:'read',answers:{},checked:{},first:{},orders:{},orderChecked:{},code:{},runs:{},tabs:{},tutor:0,legacy:null};}
let state=fresh(),entry=!teacher,live=null,storageOK=true,storageKey=prefix+'-preview',draft={name:'',className:''},expanded=null;
const questions=[...STARTER,...PLENARY];
const answerKeys=new Set([...questions.map(q=>q.id),'start_focus','end_focus','exit_sentence',...CHECKS.flatMap(([id])=>['start_'+id,'now_'+id,'phase_'+id,'evidence_'+id]),...Object.values(PROGRAMS).flatMap(p=>p.tests.map((_,i)=>'test_'+p.id+'_'+i))]);
function cleanRun(r){if(!r||typeof r.code!=='string'||r.code.length>20000||!['done','error','stopped','timeout'].includes(r.status))return null;return {id:String(r.id||'').slice(0,80),at:String(r.at||'').slice(0,50),code:r.code,stdout:String(r.stdout||'').slice(0,18000),transcript:String(r.transcript||r.output||'').slice(0,24000),error:String(r.error||'').slice(0,3000),status:r.status,inputs:Array.isArray(r.inputs)?r.inputs.filter(x=>typeof x==='string').slice(0,40).map(x=>x.slice(0,500)):[]};}
function validate(raw){if(raw?.app!==APP||raw.version!==VERSION)throw Error('Wrong lesson');const s=fresh();s.name=String(raw.name||'').slice(0,100);s.className=String(raw.className||'').slice(0,60);s.lang=['en','ms','zh'].includes(raw.lang)?raw.lang:'en';s.compare=raw.compare===true;s.guided=matchesSupport(s.name)||(teacher&&raw.guided===true);s.page=PAGES.some(p=>p[0]===raw.page)?raw.page:'read';s.tutor=Number.isInteger(raw.tutor)?Math.max(0,Math.min(8,raw.tutor)):0;
 for(const k of answerKeys)if(typeof raw.answers?.[k]==='string'&&raw.answers[k].length<=6000)s.answers[k]=raw.answers[k];
 for(const q of questions){if(!q.options[Number(s.answers[q.id])]||!/^\d+$/.test(s.answers[q.id]||''))delete s.answers[q.id];if(raw.checked?.[q.id]===true&&s.answers[q.id]!==undefined)s.checked[q.id]=true;if(/^\d+$/.test(raw.first?.[q.id]||'')&&q.options[Number(raw.first[q.id])])s.first[q.id]=raw.first[q.id];}
 for(const [id]of CHECKS){if(!['starter','blocks','run','help','untried'].includes(s.answers['evidence_'+id]))delete s.answers['evidence_'+id];for(const pre of ['start','now'])if(!['independent','support','need','untried'].includes(s.answers[pre+'_'+id]))delete s.answers[pre+'_'+id];if(![...PHASES.map(x=>x[0]),'untried'].includes(s.answers['phase_'+id]))delete s.answers['phase_'+id];}
 for(const k of ['start_focus','end_focus'])if(!['meaning','practice','explain','help','challenge'].includes(s.answers[k]))delete s.answers[k];
 for(const[id,p]of Object.entries(PARSONS)){const o=raw.orders?.[id];if(Array.isArray(o)&&o.length===p.blocks.length&&new Set(o).size===o.length&&o.every(x=>Number.isInteger(x)&&x>=0&&x<p.blocks.length)){s.orders[id]=o;if(raw.orderChecked?.[id]===true)s.orderChecked[id]=true;}}
 for(const[id,p]of Object.entries(PROGRAMS)){if(typeof raw.code?.[id]==='string'&&raw.code[id].length<=20000)s.code[id]=raw.code[id];if(Array.isArray(raw.runs?.[id]))s.runs[id]=raw.runs[id].slice(-30).map(cleanRun).filter(Boolean);}
 for(const page of PAGES.map(p=>p[0]))if(PROGRAMS[raw.tabs?.[page]]?.page===page)s.tabs[page]=raw.tabs[page];
 if(raw.legacy?.app==='year9-helpdesk-project'&&JSON.stringify(raw.legacy).length<7000000)s.legacy=raw.legacy;
 return s;
}
function readSaved(key){try{const raw=localStorage.getItem(key);return raw?validate(JSON.parse(raw)):null;}catch{storageOK=false;return null;}}
try{const identity=JSON.parse(localStorage.getItem(prefix+'-identity')||'null');if(identity){draft={name:String(identity.name||'').slice(0,100),className:String(identity.className||'').slice(0,60)};storageKey=prefix+'-'+encodeURIComponent(normalize(draft.name)||'preview');}state=readSaved(storageKey)||fresh();if(!state.name){state.name=draft.name;state.className=draft.className;state.guided=matchesSupport(state.name);}if(teacher&&params.get('guided')==='1'){storageKey=prefix+'-guided-preview';state=readSaved(storageKey)||fresh();state.guided=true;}}catch{storageOK=false;}
function txt(b){return typeof b==='string'?b:b?.[state.lang]??b?.en??'';}
function bi(b){if(typeof b==='string')return esc(b);let out=`<span lang="${state.lang==='zh'?'zh-Hans':state.lang}">${esc(txt(b))}</span>`;if(state.guided){const support=state.lang==='zh'?b.en:b.zh;out+=`<span class="translation" lang="${state.lang==='zh'?'en':'zh-Hans'}">${esc(support)}</span>`;}else if(state.compare&&state.lang!=='en')out=`<span lang="en">${esc(b.en)}</span><span class="translation" lang="${state.lang==='zh'?'zh-Hans':state.lang}">${esc(txt(b))}</span>`;return out;}
const t=(en,ms,zh)=>bi(B(en,ms,zh));
const val=id=>state.answers[id]||'';
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}const s=document.getElementById('save-status');if(s)s.textContent=txt(storageOK?L.saved:L.saveError);}
function begin(){if(live)finish('stopped');save();const guided=matchesSupport(draft.name),key=prefix+'-'+encodeURIComponent(normalize(draft.name));const previousLang=state.lang;state=readSaved(key)||fresh();state.name=draft.name.trim();state.className=draft.className.trim();state.guided=guided;state.lang=previousLang;storageKey=key;try{localStorage.setItem(prefix+'-identity',JSON.stringify({name:state.name,className:state.className}));}catch{}entry=false;save();render();window.scrollTo(0,0);}
function notice(b){const el=document.getElementById('notice');el.textContent=txt(b);clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.textContent='',6500);}
function codeMarkup(code){return esc(code).replace(/(#[^\n]*|&quot;.*?&quot;|&#39;.*?&#39;|\b(?:if|else|elif|and|or|not|True|False|input|int|print)\b|\b\d+\b)/g,token=>`<span class="${token[0]==='#'?'syn-comment':token.startsWith('&')?'syn-string':/^\d/.test(token)?'syn-number':'syn-key'}">${token}</span>`);}
const codeBox=code=>`<pre class="code-sample"><code>${codeMarkup(code)}</code></pre>`;
const card=(title,body,cls='')=>`<section class="card ${cls}"><h2>${bi(title)}</h2>${body}</section>`;
const para=b=>`<p>${bi(b)}</p>`;
function select(id,label,options){return `<label class="field" for="${id}"><span>${bi(label)}</span><select id="${id}" data-answer="${id}"><option value="">${esc(txt(L.choose))}</option>${options.map(([value,title])=>`<option value="${esc(value)}" ${val(id)===value?'selected':''}>${esc(txt(title))}</option>`).join('')}</select></label>`;}
function langControl(){return `<label class="language">${t('Language','Bahasa','语言')}<select data-lang aria-label="${esc(txt(B('Reading language','Bahasa bacaan','阅读语言')))}">${[['en','English'],['ms','Bahasa Melayu'],['zh','简体中文']].map(([v,n])=>`<option value="${v}" ${state.lang===v?'selected':''}>${n}</option>`).join('')}</select></label>`;}
function aims(){return `<div class="aim-card"><span class="eyebrow">WAGBA</span><p>${bi(L.wagba)}</p></div><div class="aims-grid">${['K','S','U'].map((k,i)=>`<div class="aim-mini"><b><span class="letter">${k}</span>${bi(L[k])}</b><p>${bi(L[['knowledge','skills','understanding'][i]])}</p></div>`).join('')}</div>`;}
function welcome(){return `<main id="main" class="landing"><header><a class="brand" href="#">CS / MR DAVE</a>${langControl()}</header><div class="landing-grid"><section><span class="eyebrow">${t('Year 9 · Week 5 theory','Tahun 9 · Teori minggu 5','九年级 · 第五周理论')}</span><h1>${bi(L.title)}<span class="title-dot">.</span></h1><p class="intro">${t('From a question to a working program. Build it one small step at a time.','Daripada soalan kepada atur cara berfungsi. Bina satu langkah kecil pada satu masa.','从一个问题到可运行的程序，一次完成一个小步骤。')}</p>${aims()}<div class="learning-definition"><b>${t('Learning today','Pembelajaran hari ini','今天的学习')}</b>${para(B('Know what the code means. Practise using it. Understand why it works.','Ketahui maksud kod. Berlatih menggunakannya. Fahami sebab ia berfungsi.','知道代码的含义，练习使用它，理解它为什么这样运行。'))}</div></section><div><form id="entry-form" class="card entry-card"><span class="tag">${t('Your workspace','Ruang kerja anda','你的学习空间')}</span><h2>${t('Let’s begin','Mari mula','开始吧')}</h2><label class="field">${t('Full name','Nama penuh','姓名')}<input name="name" data-identity="name" maxlength="100" autocomplete="name" value="${esc(draft.name)}" required></label><label class="field">${t('Class','Kelas','班级')}<input name="className" data-identity="className" maxlength="60" value="${esc(draft.className)}" required></label><button class="primary wide" type="submit">${t('Open my lesson','Buka pelajaran saya','打开我的课程')} →</button><p class="small">${t('Your work saves on this browser. Use a backup when moving devices.','Kerja disimpan dalam pelayar ini. Gunakan sandaran apabila menukar peranti.','作品保存在此浏览器。更换设备时请使用备份。')}</p>${restoreControl()}</form><div class="route-preview"><span>01 <b>${t('Read & recall','Baca & ingat','阅读与回忆')}</b></span><span>02 <b>${t('Arrange & code','Susun & kod','排列与编程')}</b></span><span>03 <b>${t('Run & improve','Jalankan & perbaiki','运行与改进')}</b></span></div></div></div></main>`;}
function sidebar(){return `<aside class="sidebar"><a class="brand" href="#" data-home>CS / MR DAVE</a><p class="course-label">${t('Year 9 · Week 5 theory','Tahun 9 · Teori minggu 5','九年级 · 第五周理论')}</p><details class="lesson-menu" ${window.matchMedia?.('(min-width: 851px)').matches===false?'':'open'}><summary>${t('Lesson pages','Halaman pelajaran','课程页面')} ▾</summary><nav aria-label="${esc(txt(B('Lesson pages','Halaman pelajaran','课程页面')))}">${Object.entries(GROUPS).map(([g,label])=>`<div class="nav-group"><p>${bi(label)}</p>${PAGES.filter(p=>p[3]===g).map(p=>`<button data-page="${p[0]}" ${state.page===p[0]?'aria-current="page"':''}><span class="nav-dot"></span>${bi(p[1])}</button>`).join('')}</div>`).join('')}</nav></details><details class="sidebar-aims" ${window.matchMedia?.('(min-width: 851px)').matches===false?'':'open'}><summary>WAGBA · K · S · U</summary>${aims()}</details></aside>`;}
function render(){const page=PAGES.find(p=>p[0]===state.page)||PAGES[0];document.documentElement.lang=state.lang==='zh'?'zh-Hans':state.lang;document.getElementById('skip-link').textContent=txt(B('Skip to lesson','Langkau ke pelajaran','跳至课程'));document.getElementById('app').innerHTML=entry?welcome():`<div class="shell">${sidebar()}<div class="workspace"><header class="topbar"><div><b>${esc(state.name||txt(L.teacher))}</b><span class="small">${esc(state.className)}${teacher?' · '+esc(txt(L.teacher)):''}</span><span id="save-status">${esc(txt(storageOK?L.saved:L.saveError))}</span></div><div class="top-controls">${langControl()}${!state.guided?`<label class="compare-toggle"><input type="checkbox" data-compare ${state.compare?'checked':''}>${t('Bilingual','Dwibahasa','双语')}</label>`:`<span class="tag">${t('Step by step','Langkah demi langkah','一步一步')}</span>`}<button data-action="home">${t('Welcome','Selamat datang','欢迎页')}</button>${teacher?`<button data-action="preview-route">${state.guided?t('Standard preview','Pratonton biasa','普通预览'):t('Supported preview','Pratonton sokongan','辅助预览')}</button>`:''}</div></header><main id="main"><div class="page-heading"><div><span class="eyebrow">${bi(GROUPS[page[3]])}</span><h1 id="page-title" tabindex="-1">${bi(page[2])}</h1></div><span class="page-number">${String(PAGES.indexOf(page)+1).padStart(2,'0')} / ${PAGES.length}</span></div>${state.guided?`<p class="support-strip">${t('One small step. Short answers are enough. Ask for help when you need it.','Satu langkah kecil. Jawapan pendek memadai. Minta bantuan apabila perlu.','一次做一小步，简短回答就够了。需要时请寻求帮助。')}</p>`:''}${renderPage()}<footer class="page-footer"><button data-page="${PAGES[Math.max(0,PAGES.indexOf(page)-1)][0]}" ${PAGES.indexOf(page)===0?'disabled':''}>← ${bi(L.back)}</button><span>${bi(page[1])}</span>${PAGES.indexOf(page)<PAGES.length-1?`<button class="primary" data-page="${PAGES[PAGES.indexOf(page)+1][0]}">${bi(L.next)} →</button>`:''}</footer></main></div></div>`;bindEditors();}
function go(page){if(!PAGES.some(p=>p[0]===page))return;if(live)finish('stopped');expanded=null;state.page=page;entry=false;save();render();document.getElementById('page-title')?.focus();window.scrollTo(0,0);}
function renderPage(){switch(state.page){case'read':return readPage();case'starter':return starterPage();case'types':return reflection(false);case'reference':return referencePage();case'calculations-read':return calculationReading();case'pit':return reflection(true);case'plenary':return plenary();case'extension':return extensionPage();default:return practicePage(state.page);}}
function readPage(){return `<div class="scenario-grid">${card(B('Meet Sam','Kenali Sam','认识 Sam'),`<span class="scenario-icon" aria-hidden="true">?</span><p class="intro">${t('Sam cannot sign in. The school helpdesk can help, but other people are waiting.','Sam tidak dapat log masuk. Meja bantuan sekolah boleh membantu, tetapi orang lain sedang menunggu.','Sam 无法登录。学校服务台可以帮忙，但前面还有人在等待。')}</p>${para(B('Sam has 15 minutes before the next lesson. Should Sam ask for help now or arrange another time?','Sam mempunyai 15 minit sebelum pelajaran seterusnya. Patutkah Sam meminta bantuan sekarang atau mengatur masa lain?','离下一节课还有 15 分钟。Sam 应该现在求助，还是另约时间？'))}<div class="scenario-message"><b>Sam</b><p>${t('“There are 2 people ahead of me. Do I have enough time?”','“Ada 2 orang di hadapan saya. Adakah masa saya cukup?”','“我前面有 2 人，时间够吗？”')}</p></div>`,'scenario-card')}${card(B('Connect to our earlier work','Hubungkan dengan kerja terdahulu','联系之前的学习'),para(B('Our earlier checker used inputs, rules and advice. Today we use the same pattern for a school helpdesk.','Penyemak terdahulu menggunakan input, peraturan dan nasihat. Hari ini kita menggunakan corak sama untuk meja bantuan sekolah.','之前的检查器用输入、规则和建议工作。今天我们用同样的方法解决学校服务台的问题。'))+`<div class="flow"><span>${t('INPUT','INPUT','输入')}<b>2 · 15</b></span><i>→</i><span>${t('CALCULATE','KIRA','计算')}<b>8 + 4 = 12</b></span><i>→</i><span>${t('ADVISE','NASIHAT','建议')}<b>${t('Ask now','Tanya sekarang','现在询问')}</b></span></div>`+para(B('We estimate 4 minutes per person, including Sam. Real help can take longer. Never ask a user for a password.','Kita menganggarkan 4 minit setiap orang, termasuk Sam. Bantuan sebenar mungkin lebih lama. Jangan minta kata laluan.','估计每人 4 分钟，包括 Sam。实际帮助可能更久。不要索取密码。')))}</div><div class="three-grid">${card(B('1 · Collect','1 · Terima','1 · 获取'),para(B('Ask how many people are ahead and how many minutes are available.','Tanya bilangan orang di hadapan dan minit tersedia.','询问前面人数和可用分钟数。')))}${card(B('2 · Calculate','2 · Kira','2 · 计算'),para(B('Find the wait, then add Sam’s own help time.','Cari masa menunggu, kemudian tambah masa bantuan Sam.','求等待时间，再加上 Sam 的服务时间。')))}${card(B('3 · Choose','3 · Pilih','3 · 选择'),para(B('Compare the total with the time available. Print one useful action.','Bandingkan jumlah dengan masa tersedia. Cetak satu tindakan berguna.','比较总时间与可用时间，输出一个有用的行动建议。')))}</div>`;}
function vocabCards(){return VOCAB.map(([word,meaning,example])=>`<article class="vocab-card"><code class="word">${esc(word)}</code>${para(meaning)}${codeBox(example)}</article>`).join('');}
function mcq(q){const chosen=val(q.id),checked=state.checked[q.id];return `<article class="question-card" id="question-${q.id}"><span class="tag">${bi(L[q.area])}</span><h3>${bi(q.prompt)}</h3>${q.code?codeBox(q.code):''}<div class="choices">${q.options.map((o,i)=>`<label class="choice ${chosen===String(i)?'selected':''}"><input type="radio" name="${q.id}" data-answer="${q.id}" value="${i}" ${chosen===String(i)?'checked':''}><span>${bi(o)}</span></label>`).join('')}</div><button data-check="${q.id}">${bi(L.check)}</button><div class="question-feedback" role="status">${checked?`<div class="feedback ${chosen===String(q.answer)?'success':''}"><b>${chosen===String(q.answer)?t('Correct.','Betul.','正确。'):t('Try again.','Cuba lagi.','再试一次。')}</b>${para(q.why)}</div>`:''}</div></article>`;}
function starterPage(){return `<div class="reading-practice"><section class="card reading-column"><span class="eyebrow">${t('Read beside the questions','Baca di sebelah soalan','边阅读边做题')}</span><h2>${t('A quick reminder','Peringatan ringkas','小提示')}</h2><div class="vocab-list">${vocabCards()}</div></section><section><p class="instruction">${t('Try all six. Choose an answer, then check it. You can use the reminders.','Cuba keenam-enam. Pilih jawapan, kemudian semak. Anda boleh menggunakan peringatan.','尝试六题，选择答案后检查。可以参考左侧提示。')}</p>${STARTER.map(mcq).join('')}</section></div>`;}
function referencePage(){return `<p class="intro">${t('Read these examples before you build. Each card has one idea and a line you can recognise in a helpdesk program.','Baca contoh ini sebelum membina. Setiap kad mempunyai satu idea dan baris yang boleh dikenal dalam atur cara meja bantuan.','先读示例再编写。每张卡介绍一个概念和一行服务台程序代码。')}</p><div class="two-grid">${vocabCards()}</div>${card(B('How should I name a value?','Bagaimanakah menamakan nilai?','怎样给数值命名？'),`<div class="tablewrap"><table><thead><tr><th>${t('Unclear or invalid','Tidak jelas atau tidak sah','不清楚或无效')}</th><th>${t('Better name','Nama lebih baik','更好的名称')}</th><th>${t('Reason','Sebab','原因')}</th></tr></thead><tbody><tr><td><code>2 people</code></td><td><code>people_ahead</code></td><td>${t('Start with a letter. Use an underscore instead of a space.','Mulakan dengan huruf. Guna garis bawah, bukan ruang.','以字母开头，用下划线代替空格。')}</td></tr><tr><td><code>x</code></td><td><code>minutes_available</code></td><td>${t('Tell a reader what the number means.','Beritahu pembaca maksud nombor.','让读者知道这个数字的含义。')}</td></tr><tr><td><code>time</code></td><td><code>MINUTES_PER_PERSON</code></td><td>${t('Show the unit and the intended constant.','Tunjukkan unit dan pemalar.','说明单位，并表示这是预定常量。')}</td></tr></tbody></table></div>`)}`;}
const SAMPLE={
 inputs:['device = input("Device: ")\nprint("Device:", device)\npeople = int(input("People ahead: "))\nprint(people + 1)',B('input() gives text. int() converts a suitable whole-number answer. Use int() when you need arithmetic.','input() memberi teks. int() menukar jawapan nombor bulat yang sesuai. Guna int() untuk pengiraan.','input() 返回文本。int() 把合适的回答转换为整数。需要计算时使用 int()。')],
 constants:['MINUTES_PER_PERSON = 4\npeople_ahead = 2\npeople_ahead = people_ahead + 1\nprint(people_ahead)\nprint(MINUTES_PER_PERSON)',B('The count changes from 2 to 3. Our intended constant stays 4. Capital letters are a naming convention; Python still allows reassignment.','Kiraan berubah daripada 2 kepada 3. Pemalar kita kekal 4. Huruf besar ialah konvensyen nama; Python masih membenarkan nilai ditetapkan semula.','人数从 2 变为 3，预定常量保持为 4。大写只是命名约定，Python 仍允许重新赋值。')],
 conditions:['total_minutes = 8\nminutes_available = 10\nprint(total_minutes <= minutes_available)\nprint(total_minutes == minutes_available)',B('8 <= 10 is True. 8 == 10 is False. A comparison produces a bool. One = stores; two == compare.','8 <= 10 ialah True. 8 == 10 ialah False. Perbandingan menghasilkan bool. Satu = menyimpan; dua == membandingkan.','8 <= 10 是 True，8 == 10 是 False。比较产生 bool。一个 = 保存值；两个 == 比较。')],
 calculations:['MINUTES_PER_PERSON = 4\npeople_ahead = 1\nwaiting_minutes = people_ahead * MINUTES_PER_PERSON\ntotal_minutes = waiting_minutes + MINUTES_PER_PERSON\nprint("Total:", total_minutes)',B('1 × 4 = 4 minutes waiting. Add Sam’s 4 minutes: 8 in total. Calculate a value before using it on another line.','1 × 4 = 4 minit menunggu. Tambah 4 minit Sam: jumlah 8. Kira nilai sebelum menggunakannya pada baris lain.','1 × 4 = 等待 4 分钟，加上 Sam 的 4 分钟，共 8 分钟。先计算一个值，再在后续代码中使用。')],
 decisions:['total_minutes = 8\nminutes_available = 10\nif total_minutes <= minutes_available:\n    print("Ask the helpdesk if they can help now.")\nelse:\n    print("Arrange another time.")',B('True runs the indented if block. False runs the else block. Each branch starts with a colon. Keep four spaces before its print line.','True menjalankan blok if berinden. False menjalankan else. Setiap cabang bermula dengan titik bertindih. Kekalkan empat ruang sebelum print.','True 执行缩进的 if 代码块，False 执行 else。每个分支用冒号开始，print 前保留四个空格。')]
};
function order(id){return state.orders[id]||PARSONS[id].start;}
function ordered(id){return order(id).every((n,i)=>n===i);}
function puzzleHTML(id){const p=PARSONS[id];return `<article class="card puzzle" id="puzzle-${id}"><span class="eyebrow">${bi(L.parsons)}</span><h2>${bi(p.title)}</h2>${para(p.instruction)}<p class="small">${t('Move blocks with ↑ and ↓. Keep the spaces inside each block.','Alih blok dengan ↑ dan ↓. Kekalkan ruang dalam setiap blok.','用 ↑ 和 ↓ 移动代码块，保留块内空格。')}</p><ol class="parsons-list">${order(id).map((n,i)=>`<li><b class="position">${i+1}</b><pre><code>${codeMarkup(p.blocks[n])}</code></pre><div class="move-buttons">${[-1,1].map(d=>`<button data-move="${id}" data-pos="${i}" data-dir="${d}" ${i+d<0||i+d>=p.blocks.length?'disabled':''} aria-label="${esc(txt(d===-1?B('Move block '+(i+1)+' up','Alih blok '+(i+1)+' ke atas','将第 '+(i+1)+' 块上移'):B('Move block '+(i+1)+' down','Alih blok '+(i+1)+' ke bawah','将第 '+(i+1)+' 块下移')))}">${d===-1?'↑':'↓'}</button>`).join('')}</div></li>`).join('')}</ol><button data-order-check="${id}">${t('Check the order','Semak susunan','检查顺序')}</button><div role="status">${state.orderChecked[id]?`<div class="feedback ${ordered(id)?'success':''}"><b>${ordered(id)?t('The order works.','Susunan ini betul.','这个顺序可以运行。'):t('Move a block and try again.','Alih satu blok dan cuba lagi.','移动一块，再试试。')}</b>${para(p.hint)}</div>`:''}</div></article>`;}
function practicePage(page){const ids=Object.values(PROGRAMS).filter(p=>p.page===page).map(p=>p.id),current=ids.includes(state.tabs[page])?state.tabs[page]:ids[0];const sample=SAMPLE[page];return `${card(L.sample,`<div class="example-grid">${codeBox(sample[0])}<div>${para(sample[1])}${page==='decisions'?`<div class="mini-rule">12 &lt;= 15 → <b>True</b><br>20 &lt;= 15 → <b>False</b><br>12 &lt;= 12 → <b>True</b></div>`:''}</div>`,'example-card')}<div class="two-grid puzzle-grid">${Object.values(PARSONS).filter(p=>p.page===page).map(p=>puzzleHTML(p.id)).join('')}</div><section class="coding-workshop"><div class="section-heading"><span class="eyebrow">${bi(L.practice)}</span><h2>${t('Now make it run','Kini jalankannya','现在，让它运行')}</h2></div>${ids.length>1?`<div class="exercise-tabs" role="tablist" aria-label="${esc(txt(L.practice))}">${ids.map(id=>`<button role="tab" aria-selected="${id===current}" data-exercise="${id}">${bi(PROGRAMS[id].title)}</button>`).join('')}</div>`:''}<div id="exercise-body">${exercise(current)}</div></section>`;}
function starterCode(id){return state.code[id]??(state.guided?PROGRAMS[id].guided:PROGRAMS[id].starter);}
function exercise(id){const p=PROGRAMS[id];return `<div class="task-brief"><span class="tag">${bi(L.try)}</span><h3>${bi(p.title)}</h3>${para(state.guided?GUIDED_TASKS[id]:p.task)}${state.guided?`<div class="word-bank"><b>${t('Words and symbols to try','Perkataan dan simbol untuk dicuba','可尝试的词与符号')}</b><p><code>${esc(({input_text:'name',input_number:'1',input_pair:'minutes_available',constant_edit:'1',condition_check:'<=',calculate_wait:'*',calculate_total:'+',calculate_spare:'-',core:'*   +   <=',extension:'BUFFER_MINUTES'})[id]||'')}</code></p></div><p class="support-strip">${t('Replace each ___ gap. Run once, then try the next example.','Gantikan setiap ___. Jalankan sekali, kemudian cuba contoh seterusnya.','替换每个 ___ 空白。运行一次，再尝试下一个例子。')}</p>`:''}${id==='core'?`<div class="build-strip"><p>${t('First check both puzzles on Calculate time and puzzle 1 on this page. Then join those blocks into your full program.','Semak kedua-dua teka-teki Kira masa dan teka-teki 1 halaman ini. Kemudian gabungkan blok itu menjadi atur cara lengkap.','先检查“计算时间”页的两道排序题和本页的第 1 题，然后把这些代码块连接成完整程序。')}</p><button data-assemble>${t('Assemble my full program','Gabungkan atur cara lengkap saya','组成我的完整程序')}</button></div>`:''}</div>${ide(id)}${testCards(id)}${teacher?`<details class="teacher-model"><summary>${t('Teacher: worked solution','Guru: penyelesaian contoh','教师：参考代码')}</summary>${codeBox(p.solution)}</details>`:''}`;}
function ide(id){const code=starterCode(id);return `<section class="ide ${expanded===id?'expanded':''}" id="ide-${id}" aria-label="${esc(txt(B('Python workspace','Ruang kerja Python','Python 编程空间')))}"><header class="ide-toolbar"><div class="file-tab"><span class="python-mark">Py</span> ${id==='core'?'helpdesk':id}.py</div><div><button class="run-button" data-run="${id}" ${live?'disabled':''}>▶ ${bi(L.run)}</button><button data-stop ${live?.program===id?'':'disabled'}>■ ${bi(L.stop)}</button><button data-download="${id}" title="${esc(txt(L.download))}" aria-label="${esc(txt(L.download))}">↓ .py</button><button data-expand="${id}" aria-label="${esc(txt(B('Expand or reduce editor','Besarkan atau kecilkan editor','展开或缩小编辑器')))}">⛶</button></div></header><div class="ide-panes"><div class="editor-pane"><div class="pane-label">${t('CODE','KOD','代码')}<span>Python 3</span></div><div class="code-wrap"><div id="gutter-${id}" class="line-numbers" aria-hidden="true">${code.split('\n').map((_,i)=>i+1).join('\n')}</div><div class="editor-stack"><pre id="highlight-${id}" class="highlight" aria-hidden="true">${codeMarkup(code)}\n</pre><textarea id="code-${id}" data-code="${id}" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" aria-label="${esc(txt(B('Python code','Kod Python','Python 代码')))} ${id}" ${live?'readonly':''}>${esc(code)}</textarea></div></div><div class="editor-hint">${t('Tab = 4 spaces · Ctrl/⌘ + Enter = Run','Tab = 4 ruang · Ctrl/⌘ + Enter = Jalankan','Tab = 4 个空格 · Ctrl/⌘ + Enter = 运行')}</div></div><div class="console-pane"><div class="pane-label">${bi(L.console)}<button data-clear="${id}">${t('Clear display','Kosongkan paparan','清空显示')}</button></div><div class="terminal" id="console-${id}">${consoleHTML(id)}</div></div></div><div class="ide-bottom"><span>${t('Your code and run history save automatically.','Kod dan sejarah larian disimpan secara automatik.','代码和运行记录自动保存。')}</span><button data-starter="${id}">${t('Use a starter','Guna kod permulaan','使用起始代码')}</button></div></section><details class="run-history"><summary>${t('Previous runs','Larian terdahulu','之前的运行')} (${(state.runs[id]||[]).length})</summary><div id="history-${id}">${historyHTML(id)}</div></details>`;}
const cleared=new Set();
function consoleHTML(id){const job=live?.program===id?live:null,r=job?.run||(!cleared.has(id)?state.runs[id]?.at(-1):null);if(!r)return `<p class="terminal-welcome">${bi(L.ready)}</p>`;return `<pre class="transcript">${esc(r.transcript)}</pre>${job?.pending?`<form class="terminal-input" data-input="${id}"><label for="response-${id}">${esc(job.pending.prompt)}</label><input id="response-${id}" name="response" maxlength="500" aria-label="${esc(job.pending.prompt||txt(B('Program input','Input atur cara','程序输入')))}" autocomplete="off" autocapitalize="off" spellcheck="false"><button type="submit" aria-label="${esc(txt(B('Send input','Hantar input','提交输入')))}">↵</button></form><p class="terminal-help">${t('Type here and press Enter.','Taip di sini dan tekan Enter.','在这里输入，按 Enter。')}</p>`:''}${r.error?`<pre class="terminal-error">${esc(r.error)}</pre><p>${errorHint(r.error)}</p>`:''}${!job?`<div class="terminal-status">${r.status==='done'?t('Program finished','Atur cara selesai','程序结束'):r.status==='stopped'?t('Program stopped','Atur cara dihentikan','程序已停止'):t('Check your code, then Run again','Semak kod, kemudian Jalankan semula','检查代码后再运行')}</div>${r.code!==starterCode(id)?`<p class="stale">${t('Code changed since this run. Run again.','Kod berubah selepas larian ini. Jalankan semula.','代码已改变，请重新运行。')}</p>`:''}`:''}`;}
function errorHint(error){return /ValueError/.test(error)?t('int() needs a whole number such as 2. Run again and enter digits.','int() memerlukan nombor bulat seperti 2. Jalankan semula dan masukkan digit.','int() 需要像 2 这样的整数。重新运行并输入数字。'):/NameError/.test(error)?t('Check spelling and replace every ___ gap. Store a value before using its name.','Semak ejaan dan gantikan semua ___. Simpan nilai sebelum menggunakan namanya.','检查拼写，替换所有 ___。使用名称前先给它赋值。'):/SyntaxError|IndentationError/.test(error)?t('Check quotes, brackets, colons and four-space indentation.','Semak petikan, kurungan, titik bertindih dan inden empat ruang.','检查引号、括号、冒号和四空格缩进。'):t('Read the error and check that line. Ask for help if needed.','Baca ralat dan semak baris itu. Minta bantuan jika perlu.','阅读错误信息，检查对应行。需要时请寻求帮助。');}
function historyHTML(id){return (state.runs[id]||[]).slice().reverse().map(r=>`<article><b>${esc(r.at)} · ${esc(r.status)}</b><pre>${esc(r.transcript+(r.error?'\n'+r.error:''))}</pre><details><summary>${t('Code used','Kod digunakan','所用代码')}</summary>${codeBox(r.code)}</details></article>`).join('')||para(L.noEvidence);}
function matchingRun(id,inputs){return (state.runs[id]||[]).slice().reverse().find(r=>r.status==='done'&&r.code===starterCode(id)&&r.inputs.length===inputs.length&&r.inputs.every((v,i)=>v===inputs[i]));}
function testCards(id){return `<section class="test-section" id="tests-${id}"><h3>${t('Run these examples','Jalankan contoh ini','运行这些例子')}</h3><p class="small">${t('These are test values, not input boxes. Press Run, then type each value when the console asks.','Ini nilai ujian, bukan kotak input. Tekan Jalankan, kemudian taip setiap nilai apabila konsol bertanya.','这里是测试值，不是输入框。点击运行，控制台提问时再依次输入。')}</p><div class="test-grid">${PROGRAMS[id].tests.map(([inputs,expected],i)=>{const r=matchingRun(id,inputs),match=r&&r.stdout.trim()===expected.trim();return `<article class="test-card"><span class="tag">${t('Case','Kes','案例')} ${String.fromCharCode(65+i)}</span><h4>${t('Type in this order','Taip mengikut urutan','按这个顺序输入')}</h4><div class="input-chips">${inputs.map(x=>`<code>${esc(x)}</code>`).join('<span>→</span>')}</div><p class="small">${t('Expected output','Output dijangka','预期输出')}</p><pre>${esc(expected)}</pre><div class="test-result ${match?'pass':''}">${r?match?t('✓ This run matches.','✓ Larian ini sepadan.','✓ 本次运行符合。'):t('Output differs. Compare the words and numbers.','Output berbeza. Bandingkan perkataan dan nombor.','输出不同，请对照文字和数字。'):t('Not run with this version yet.','Belum dijalankan dengan versi ini.','尚未用当前版本运行。')}</div>${r?`<details><summary>${t('My actual output','Output sebenar saya','我的实际输出')}</summary><pre>${esc(r.stdout)}</pre></details>`:''}</article>`;}).join('')}</div><p class="small">${t('The checks compare these examples only. They do not prove the program works for every possible input.','Semakan hanya membandingkan contoh ini. Ia tidak membuktikan atur cara berfungsi untuk semua input.','检查只比较这些例子，不能证明程序对所有输入都正确。')}</p></section>`;}
function calculationReading(){return `${card(B('Operators are instructions for numbers','Operator ialah arahan untuk nombor','运算符告诉程序怎样处理数字'),`<div class="tablewrap"><table><thead><tr><th>Python</th><th>${t('Meaning','Maksud','含义')}</th><th>${t('Example','Contoh','示例')}</th><th>${t('Result','Hasil','结果')}</th></tr></thead><tbody>${[['+',B('Add','Tambah','加'),'8 + 4','12'],['-',B('Subtract','Tolak','减'),'15 - 12','3'],['*',B('Multiply','Darab','乘'),'3 * 4','12'],['/',B('Divide','Bahagi','除'),'12 / 4','3.0'],['//',B('Floor division','Pembahagian lantai','向下取整除法'),'13 // 4','3'],['%',B('Remainder','Baki','余数'),'13 % 4','1'],['**',B('Power','Kuasa','幂'),'2 ** 3','8']].map(([s,m,e,r])=>`<tr><td><code>${s}</code></td><td>${bi(m)}</td><td><code>${e}</code></td><td><b>${r}</b></td></tr>`).join('')}</tbody></table></div><p>${t('For 13 minutes in 4-minute groups: 3 whole groups use 12 minutes, leaving 1. Python multiplies before adding; brackets group a calculation.','Untuk 13 minit dalam kumpulan 4 minit: 3 kumpulan penuh menggunakan 12 minit, berbaki 1. Python mendarab sebelum menambah; kurungan mengumpulkan pengiraan.','13 分钟按每组 4 分钟分：3 整组用掉 12 分钟，余 1 分钟。Python 先乘后加，括号可将计算分组。')}</p>`)}<div class="two-grid">${card(B('Useful number functions','Fungsi nombor berguna','有用的数值函数'),codeBox('print(int("12"))   # 12\nprint(round(3.6))  # 4\nprint(max(0, -2))  # 0')+para(B('int converts. round rounds. max chooses the greatest value. Our core adviser needs int(), * and +.','int menukar. round membundarkan. max memilih nilai terbesar. Penasihat utama memerlukan int(), * dan +.','int 转换，round 四舍五入，max 选择最大值。核心建议程序需要 int()、* 和 +。')))}${card(B('Calculate the whole visit','Kira keseluruhan lawatan','计算整个服务时间'),`<div class="time-blocks"><span>4</span><span>4</span><span class="sam">Sam<br>4</span><b>= 12</b></div>`+para(B('Two people ahead: 8 minutes waiting. Sam’s own help: 4 minutes. Total: 12 minutes.','Dua orang di hadapan: menunggu 8 minit. Bantuan Sam: 4 minit. Jumlah: 12 minit.','前面两人：等待 8 分钟。Sam 的帮助：4 分钟。总共 12 分钟。')))}</div>${card(B('Line-by-line tutor','Tutor baris demi baris','逐行讲解'),tutor())}<div class="two-grid">${card(B('Example 1 · Enough time','Contoh 1 · Masa cukup','示例 1 · 时间够用'),codeBox('total_minutes = 8\nminutes_available = 10\nif total_minutes <= minutes_available:\n    print("Ask about help now.")\nelse:\n    print("Arrange another time.")')+para(B('8 <= 10 is True. The first print runs.','8 <= 10 ialah True. print pertama berjalan.','8 <= 10 为 True，执行第一条 print。')))}${card(B('Example 2 · Not enough time','Contoh 2 · Masa tidak cukup','示例 2 · 时间不够'),codeBox('total_minutes = 16\nminutes_available = 10\nif total_minutes <= minutes_available:\n    print("Ask about help now.")\nelse:\n    print("Arrange another time.")')+para(B('16 <= 10 is False. The else print runs.','16 <= 10 ialah False. print dalam else berjalan.','16 <= 10 为 False，执行 else 中的 print。')))}</div>`;}
let tutorCase=2;
function tutor(){const n=state.tutor,total=(tutorCase+1)*4,yes=total<=15;const lines=FULL.trim().split('\n');lines[1]='people_ahead = '+tutorCase;lines[2]='minutes_available = 15';const executed=[0,1,2,3,4,5,6,7,yes?8:10],active=executed[n];const notes=[B('Store the intended constant: 4 minutes for each person.','Simpan pemalar: 4 minit untuk setiap orang.','存储预定常量：每人 4 分钟。'),B('Store '+tutorCase+' people ahead. In your program, input() collects this number.','Simpan '+tutorCase+' orang di hadapan. Dalam atur cara anda, input() menerima nombor ini.','存储前面 '+tutorCase+' 人。在你的程序中，input() 获取这个数字。'),B('Store 15 available minutes.','Simpan 15 minit tersedia.','存储可用时间 15 分钟。'),B('Multiply '+tutorCase+' × 4. Waiting time is '+(tutorCase*4)+'.','Darab '+tutorCase+' × 4. Masa menunggu ialah '+(tutorCase*4)+'.','计算 '+tutorCase+' × 4，等待时间为 '+(tutorCase*4)+'。'),B('Add 4 for Sam. Total time is '+total+'.','Tambah 4 untuk Sam. Jumlah masa ialah '+total+'.','加上 Sam 的 4 分钟，总时间为 '+total+'。'),B('Print the waiting time. Stored values do not change.','Cetak masa menunggu. Nilai disimpan tidak berubah.','输出等待时间，保存的值不变。'),B('Print the total time.','Cetak jumlah masa.','输出总时间。'),B(total+' <= 15 is '+(yes?'True':'False')+'. Choose the '+(yes?'if':'else')+' path.',total+' <= 15 ialah '+(yes?'True':'False')+'. Pilih laluan '+(yes?'if':'else')+'.',total+' <= 15 为 '+(yes?'True':'False')+'，选择 '+(yes?'if':'else')+' 分支。'),B('Print one advice. Skip the other branch.','Cetak satu nasihat. Langkau cabang lain.','输出一条建议，跳过另一条分支。')];return `<div id="tutor"><div class="actions"><button data-tutor-case="2" aria-pressed="${tutorCase===2}">2 ${t('people ahead','orang di hadapan','人在前面')}</button><button data-tutor-case="4" aria-pressed="${tutorCase===4}">4 ${t('people ahead','orang di hadapan','人在前面')}</button></div><div class="tutor-grid"><ol class="trace-code">${lines.map((line,i)=>`<li ${i===active?'aria-current="step"':''}>${codeMarkup(line)}</li>`).join('')}</ol><div class="tutor-note"><span class="tag">${t('Line','Baris','行')} ${active+1} · ${n+1}/9</span>${para(notes[n])}<dl><dt>waiting_minutes</dt><dd>${n>=3?tutorCase*4:'—'}</dd><dt>total_minutes</dt><dd>${n>=4?total:'—'}</dd></dl><div class="actions"><button data-tutor="-1" ${n===0?'disabled':''}>← ${bi(L.back)}</button><button class="primary" data-tutor="1">${n===8?t('Replay','Ulang','重播'):t('Next line','Baris seterusnya','下一行')} →</button></div></div></div></div>`;}
function focusSummary(prefix){const counts=['K','S','U'].map(area=>{const ids=CHECKS.filter(c=>c[1]===area).map(c=>c[0]);return {area,independent:ids.filter(id=>val(prefix+'_'+id)==='independent').length,need:ids.filter(id=>['support','need'].includes(val(prefix+'_'+id))).length,pending:ids.filter(id=>!val(prefix+'_'+id)||val(prefix+'_'+id)==='untried').length};});const max=Math.max(...counts.map(x=>x.need)),leaders=counts.filter(x=>x.need===max),pending=counts.reduce((n,c)=>n+c.pending,0);return `<div class="three-grid score-grid">${counts.map(c=>`<div><span class="letter">${c.area}</span><b>${bi(L[c.area])}</b><strong>${c.need}/2</strong><span>${t('to practise','untuk dilatih','需要练习')}</span><p class="small">${c.independent}/2 ${t('independent','berdikari','独立完成')} · ${c.pending}/2 ${t('not tried / not chosen','belum dicuba / dipilih','未尝试／未选择')}</p></div>`).join('')}</div><p class="focus-result">${max?`${t('Your main practice area','Bidang latihan utama anda','你的主要练习领域')}: <b>${leaders.map(c=>bi(L[c.area])).join(' + ')}</b>. ${t('These have the most checks needing practice or help.','Ini mempunyai paling banyak semakan yang perlukan latihan atau bantuan.','这些方面需要练习或帮助的项目最多。')}`:pending?t('Choose a response for the checks you have tried.','Pilih respons bagi semakan yang telah dicuba.','评价你已尝试的项目。'):t('You can do all six independently. Try the further challenge.','Anda boleh melakukan keenam-enam sendiri. Cuba cabaran lanjutan.','六项都能独立完成。试试进阶挑战。')}${pending?' '+t('Untried is not counted as wrong.','Belum dicuba tidak dikira salah.','未尝试不算错误。'):''}</p>`;}
function phaseSummary(){const counts=PHASES.map(([id])=>({id,count:CHECKS.filter(([key])=>val('phase_'+key)===id).length})),total=counts.reduce((n,x)=>n+x.count,0),max=Math.max(...counts.map(x=>x.count)),leaders=counts.filter(x=>x.count===max),help=CHECKS.filter(([id])=>val('phase_'+id)==='drowning');return `<div class="phase-grid">${PHASES.map(([id,desc])=>`<div class="phase-${id}"><b>${bi(L[id])}</b><strong>${counts.find(x=>x.id===id).count}/${total||6}</strong></div>`).join('')}</div><p class="focus-result">${total?`${max>total/2?t('Your majority phase','Fasa majoriti anda','你的多数阶段'):leaders.length>1?t('Your tied highest phases','Fasa tertinggi seri','并列最多的阶段'):t('Your most selected phase','Fasa paling dipilih','选择最多的阶段')}: <b>${leaders.map(x=>bi(L[x.id])).join(' + ')}</b> (${max}/${total}).`:t('Choose a phase for each topic you have tried.','Pilih fasa bagi setiap topik yang telah dicuba.','为每个尝试过的主题选择阶段。')}${total<6?' '+t('Untried or unselected topics are kept separate.','Topik belum dicuba atau dipilih diasingkan.','未尝试或未选择的主题单独记录。'):''}</p>${help.length?`<p class="support-strip">${t('Ask for help with','Minta bantuan untuk','请在这些方面寻求帮助')}: ${help.map(x=>bi(PIT_TOPICS[x[0]])).join(' ')} ${t('Ask your teacher to show you one small step.','Minta guru menunjukkan satu langkah kecil.','请老师示范一个小步骤。')}</p>`:''}`;}
function evidenceHTML(check){const[id,area,label,qid,pid]=check,q=STARTER.find(q=>q.id===qid),answer=val(qid),r=state.runs[pid]?.at(-1);return `<details class="evidence"><summary>${t('Look at my work','Lihat kerja saya','查看我的作品')}</summary><p><b>${t('Starter answer','Jawapan permulaan','课前答案')}:</b> ${answer?bi(q.options[Number(answer)]):bi(L.noEvidence)}</p>${r?`<p><b>${bi(PROGRAMS[pid].title)}</b> · ${esc(r.status)}</p><pre>${esc(r.transcript+(r.error?'\n'+r.error:''))}</pre>${r.code!==starterCode(pid)?para(B('The code has changed since this run. Run again for current evidence.','Kod berubah selepas larian ini. Jalankan semula untuk bukti semasa.','代码在这次运行后已改变。请重新运行获取当前证据。')):''}`:para(B('No run recorded for this skill yet.','Belum ada larian direkodkan untuk kemahiran ini.','这项技能还没有运行记录。'))}</details>`;}
function pitStop(){return `<p class="intro">${t('Choose the learning phase that best describes your confidence with each topic. Leave topics you have not tried blank.','Pilih fasa pembelajaran yang paling menggambarkan keyakinan anda bagi setiap topik. Biarkan topik yang belum dicuba kosong.','为每个主题选择最符合你信心程度的学习阶段。还没尝试的主题可以留空。')}</p>${card(B('What do the four phases mean?','Apakah maksud empat fasa ini?','四个阶段是什么意思？'),`<div class="phase-grid phase-key">${PHASES.map(([id,desc])=>`<div class="phase-${id}"><b>${bi(L[id])}</b>${para(desc)}</div>`).join('')}</div>`)}<div class="reflection-grid">${['K','S','U'].map(area=>card(L[area],CHECKS.filter(c=>c[1]===area).map(([id])=>`<div class="reflection-check"><h3>${bi(PIT_TOPICS[id])}</h3>${select('phase_'+id,B('My confidence with this topic','Keyakinan saya bagi topik ini','我对这个主题的信心'),PHASES.map(([phase])=>[phase,L[phase]]))}</div>`).join(''))).join('')}</div>${card(B('My learning phase summary','Rumusan fasa pembelajaran saya','我的学习阶段汇总'),`<div id="phase-summary">${phaseSummary()}</div>`)}`;}
function reflection(end){if(end)return pitStop();const prefix=end?'now':'start';return `<p class="intro">${end?t('Look at your work. What can you do now, and how does that learning feel?','Lihat kerja anda. Apakah yang boleh dilakukan sekarang, dan bagaimana pengalaman pembelajaran itu?','看看你的作品。现在能做什么？学习这些内容的体验如何？'):t('Use your starter answers. Choose what you can do, then choose one focus. No paragraph needed.','Gunakan jawapan permulaan. Pilih perkara yang boleh dilakukan, kemudian satu fokus. Tidak perlu perenggan.','参考课前答案，选择自己能做什么，再选一个重点。不用写一段话。')}</p>${end?card(B('Which phase describes each topic?','Fasa manakah menerangkan setiap topik?','每个主题处于哪个阶段？'),`<div class="phase-grid phase-key">${PHASES.map(([id,desc])=>`<div class="phase-${id}"><b>${bi(L[id])}</b>${para(desc)}</div>`).join('')}</div>`):''}<div class="reflection-grid">${['K','S','U'].map(area=>card(L[area],CHECKS.filter(c=>c[1]===area).map(check=>{const[id,,label,qid,pid]=check;return `<div class="reflection-check"><h3>${bi(label)}</h3>${end?`<p class="small">${t('Earlier','Sebelum ini','之前')}: ${val('start_'+id)?bi(L[val('start_'+id)]):bi(L.noEvidence)}</p>`:''}${evidenceHTML(check)}${select(prefix+'_'+id,end?B('What can I do now?','Apakah yang boleh saya buat kini?','现在我能做到什么？'):B('My starting point','Titik permulaan saya','我的起点'),['independent','support','need','untried'].map(v=>[v,L[v]]))}${end?select('phase_'+id,B('My learning phase for this topic','Fasa pembelajaran untuk topik ini','这个主题的学习阶段'),[...PHASES.map(([v])=>[v,L[v]]),['untried',L.untried]])+select('evidence_'+id,B('What supports my choice?','Apakah yang menyokong pilihan saya?','什么作品支持我的选择？'),[['starter',B('My starter answer','Jawapan permulaan saya','我的课前答案')],['blocks',B('My checked code blocks','Blok kod disemak','我检查过的代码块')],['run',B('My program and its output above','Atur cara dan output saya di atas','上面的程序与输出')],['help',B('I need help finding evidence','Saya perlu bantuan mencari bukti','我需要帮助寻找证据')],['untried',L.untried]]):''}</div>`;}).join(''))).join('')}</div>${card(end?B('My progress','Kemajuan saya','我的进步'):B('My focus today','Fokus saya hari ini','今天的重点'),`<div id="focus-summary">${focusSummary(prefix)}</div>${end?`<div id="phase-summary">${phaseSummary()}</div>`:''}${select(end?'end_focus':'start_focus',B('What will help me next?','Apakah yang membantu saya seterusnya?','下一步怎样帮助自己？'),[['meaning',B('Review a meaning with the example cards','Semak maksud dengan kad contoh','用示例卡复习一个含义')],['practice',B('Practise the blocks, then try without them','Latih blok, kemudian cuba tanpanya','先练习代码块，再不看它尝试')],['explain',B('Change a test input and follow the changed output','Ubah input ujian dan ikuti perubahan output','改变一个输入，跟随输出变化')],['help',B('Ask someone to show the line where I am stuck','Minta seseorang tunjuk baris yang mengelirukan','请人讲解我卡住的那行')],['challenge',B('Try the busy-day challenge','Cuba cabaran hari sibuk','尝试忙碌日挑战')]])}`)}`;}
function plenary(){return `<div class="reading-practice">${card(B('Read a completed adviser','Baca penasihat lengkap','阅读完整建议程序'),codeBox(FULL)+para(B('Trace the example code for the recall questions. Your own program remains saved separately.','Jejak kod contoh untuk soalan imbas kembali. Atur cara anda kekal disimpan berasingan.','根据示例回答复习题。你自己的程序仍单独保存。')),'reading-column')}<section>${PLENARY.map(mcq).join('')}${card(B('One thing I learned','Satu perkara dipelajari','我学到的一点'),select('exit_sentence',B('Finish: “Now I can…”','Lengkapkan: “Kini saya boleh…”','完成：“现在我会……”'),[['input',B('ask for input and convert a number.','meminta input dan menukar nombor.','获取输入并转换数字。')],['calculate',B('calculate waiting and total time.','mengira masa menunggu dan jumlah.','计算等待与总时间。')],['decision',B('use a condition to choose between two outputs.','menggunakan syarat untuk memilih antara dua output.','用条件在两种输出之间选择。')],['practise',B('identify the step I still need to practise.','mengenal pasti langkah yang masih perlu dilatih.','指出还需要练习的步骤。')]]))}</section></div>${saveCard()}`;}
function restoreControl(){return `<label class="upload-button">${bi(L.restore)}<input data-restore type="file" accept=".json,application/json"></label>`;}
function saveCard(){return card(B('Save, check, submit','Simpan, semak, hantar','保存、检查、提交'),`<ol class="save-steps"><li>${t('Save as PDF. Choose “Save as PDF” in the print window.','Simpan sebagai PDF. Pilih “Save as PDF” dalam tetingkap cetak.','保存为 PDF，在打印窗口选择“另存为 PDF”。')}</li><li>${t('Open the PDF and check your name, code and tests.','Buka PDF dan semak nama, kod dan ujian.','打开 PDF，检查姓名、代码和测试。')}</li><li>${t('Upload it to the lesson’s Teams assignment and select Turn in.','Muat naik ke tugasan Teams pelajaran ini dan pilih Turn in.','上传到本课 Teams 作业，然后点击提交。')}</li></ol><div class="actions"><button class="primary" data-action="pdf">${bi(L.pdf)}</button><button data-download="core">${bi(L.download)}</button></div><details><summary>${t('Backup and other formats','Sandaran dan format lain','备份与其他格式')}</summary><p>${t('A full backup restores editable work. A readable report is an HTML copy. Download your Python file to keep coding next time.','Sandaran penuh memulihkan kerja boleh sunting. Laporan boleh dibaca ialah salinan HTML. Muat turun fail Python untuk menyambung lain kali.','完整备份可恢复可编辑作品。可阅读报告是 HTML 副本。下载 Python 文件可以下次继续编程。')}</p><div class="actions"><button data-action="backup">${bi(L.backup)}</button><button data-action="report">${bi(L.report)}</button>${restoreControl()}</div></details><p class="small">${t('This app does not submit to Teams for you. Partial work can also be saved.','Aplikasi ini tidak menghantar ke Teams untuk anda. Kerja belum lengkap juga boleh disimpan.','此应用不会自动提交到 Teams。未完成作品也可以保存。')}</p>`,'submit-card');}
function extensionPage(){return `<p class="intro">${t('Finished the core program? Use your extra time here. Work towards the checks below; compare correct solutions, not typing speed.','Sudah menyiapkan atur cara utama? Gunakan masa tambahan di sini. Capai semakan di bawah; bandingkan penyelesaian betul, bukan kelajuan menaip.','完成主程序后，用剩余时间做这里。目标是通过下方检查，比的是正确性，不是打字速度。')}</p><div class="two-grid">${card(B('The busy-day brief','Situasi hari sibuk','忙碌日情景'),para(B('The helpdesk needs extra time between people. Add a 2-minute buffer to the whole visit. A negative number cannot describe a real queue or time allowance.','Meja bantuan memerlukan masa tambahan. Tambah penimbal 2 minit kepada keseluruhan lawatan. Nombor negatif tidak boleh menggambarkan baris gilir atau masa sebenar.','服务台需要额外时间。给整个服务过程加 2 分钟缓冲。负数不能表示实际人数或可用时间。'))+`<ol><li>${t('Bronze: calculate a total that includes the buffer.','Gangsa: kira jumlah termasuk penimbal.','铜级：总时间包括缓冲。')}</li><li>${t('Silver: keep both advice paths working.','Perak: pastikan kedua-dua laluan nasihat berfungsi.','银级：两条建议路径都能运行。')}</li><li>${t('Gold: reject negative inputs before calculating.','Emas: tolak input negatif sebelum mengira.','金级：计算前拒绝负数输入。')}</li></ol>`)}${card(B('Read this before coding','Baca sebelum mengekod','编写前先读'),codeBox('BUFFER_MINUTES = 2\n# Example of a check for a different value:\ntickets = -1\nif tickets < 0:\n    print("Please check the number.")\nelse:\n    print("Use the number.")')+para(B('or is True if either comparison is True. Put the normal calculations inside else. This task checks negative integers; handling words needs another feature.','or ialah True jika salah satu perbandingan True. Letakkan pengiraan biasa dalam else. Tugasan ini menyemak integer negatif; perkataan memerlukan ciri lain.','任一比较为 True，or 就为 True。把正常计算放进 else。本题检查负整数；处理单词需要其他功能。')))}</div><div class="actions"><button data-copy-core>${t('Copy my helpdesk code here','Salin kod meja bantuan saya ke sini','把我的服务台代码复制到这里')}</button></div>${exercise('extension')}${saveCard()}`;}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function backup(){save();download('Helpdesk-notebook.json',JSON.stringify(state,null,2),'application/json');}
function report(){let html=`<article class="report-content"><h1>${bi(L.title)}</h1><p>${esc(state.name)} · ${esc(state.className)}</p><p><b>WAGBA:</b> ${bi(L.wagba)}</p>`;
 for(const id of ['core',...Object.keys(PROGRAMS).filter(id=>id!=='core')]){const p=PROGRAMS[id],runs=state.runs[id]||[];if(!Object.hasOwn(state.code,id)&&!runs.length)continue;html+=`<h2>${bi(p.title)}</h2>${codeBox(starterCode(id))}`;for(const r of runs)html+=`<h3>${esc(r.at)} · ${esc(r.status)}</h3><pre>${esc(r.transcript+(r.error?'\n'+r.error:''))}</pre>${r.code!==starterCode(id)?`<p>${t('Code used for this run','Kod untuk larian ini','此次运行所用代码')}</p>${codeBox(r.code)}`:''}`;}
 for(const p of Object.values(PARSONS)){if(!state.orders[p.id])continue;html+=`<h2>${bi(p.title)}</h2>${codeBox(order(p.id).map(n=>p.blocks[n]).join('\n'))}<p>${state.orderChecked[p.id]?ordered(p.id)?t('Checked: correct order','Disemak: susunan betul','已检查：顺序正确'):t('Checked: needs a change','Disemak: perlu perubahan','已检查：需要修改'):t('Not checked','Belum disemak','尚未检查')}</p>`;}
 for(const q of questions){if(!val(q.id))continue;html+=`<h3>${bi(q.prompt)}</h3><p>${bi(q.options[Number(val(q.id))])}</p>${state.checked[q.id]?`<p>${Number(val(q.id))===q.answer?t('Correct on the latest check','Betul pada semakan terkini','最近检查正确'):t('Still practising','Masih berlatih','仍在练习')}</p>`:''}${state.first[q.id]!==undefined&&state.first[q.id]!==val(q.id)?`<p>${t('First answer','Jawapan pertama','首次答案')}: ${bi(q.options[Number(state.first[q.id])])}</p>`:''}`;}
 if(CHECKS.some(([id])=>val('start_'+id))){html+=`<h2>${bi(PAGES[2][1])}</h2>${focusSummary('start')}`;for(const[id,,label]of CHECKS)if(val('start_'+id))html+=`<h3>${bi(label)}</h3><p>${bi(L[val('start_'+id)])}</p>`;}
 if(CHECKS.some(([id])=>PHASES.some(([phase])=>val('phase_'+id)===phase))){html+=`<h2>${bi(PAGES[10][1])}</h2>`;for(const[id]of CHECKS)if(PHASES.some(([phase])=>val('phase_'+id)===phase))html+=`<h3>${bi(PIT_TOPICS[id])}</h3><p>${bi(L[val('phase_'+id)])}</p>`;html+=phaseSummary();}
 for(const id of ['start_focus','exit_sentence'])if(val(id))html+=`<p><b>${id.endsWith('_focus')?t('Next action','Tindakan seterusnya','下一步行动'):t('My learning','Pembelajaran saya','我的学习')}:</b> ${bi(answerMeaning(id,val(id)))}</p>`;
 if(state.legacy)html+=`<h2>${t('Earlier notebook retained','Buku nota terdahulu disimpan','保留的之前记录')}</h2><p>${t('Your earlier notebook is included in the full backup. Its Python code is below.','Buku nota terdahulu disertakan dalam sandaran penuh. Kod Pythonnya di bawah.','之前的完整记录保存在备份中。其 Python 代码如下。')}</p>${codeBox(state.legacy.code?.core||'')}`;
 return html+'</article>';
}
function evidenceLabel(v){return ({starter:B('Starter answer','Jawapan permulaan','课前答案'),blocks:B('Checked code blocks','Blok kod disemak','检查过的代码块'),run:B('Program and recorded output','Atur cara dan output direkod','程序与运行记录'),help:B('Help needed to identify evidence','Perlu bantuan mengenal pasti bukti','需要帮助寻找证据'),untried:L.untried})[v]||v;}
function answerMeaning(id,value){const map=id.endsWith('_focus')?{meaning:B('Review meanings','Semak maksud','复习含义'),practice:B('Practise then use less support','Berlatih kemudian kurangkan sokongan','练习后减少支持'),explain:B('Change an input and follow the output','Ubah input dan ikuti output','改变输入并跟随输出'),help:B('Ask for help with a line','Minta bantuan dengan baris','请人帮助讲解代码行'),challenge:B('Try the busy-day challenge','Cuba cabaran hari sibuk','尝试忙碌日挑战')}:{input:B('Collect and convert input','Terima dan tukar input','获取并转换输入'),calculate:B('Calculate waiting and total time','Kira masa menunggu dan jumlah','计算等待与总时间'),decision:B('Choose an output with a condition','Pilih output dengan syarat','用条件选择输出'),practise:B('Identify what I need to practise','Kenal pasti perkara perlu dilatih','找出需要练习的内容')};return map[value]||value;}
function printable(){if(live)finish('stopped');save();document.getElementById('print-report').innerHTML=report();window.print();}
function readable(){download('Helpdesk-report.html','<!doctype html><html lang="'+document.documentElement.lang+'"><meta charset="utf-8"><title>Helpdesk learning report</title><style>body{font:16px/1.6 sans-serif;max-width:1000px;margin:30px auto;padding:20px;color:#172331}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f2f4f7;padding:16px}.translation{display:block;color:#596471}h2{margin-top:2em}.score-grid,.phase-grid{display:flex;gap:24px;flex-wrap:wrap}strong{margin:0 8px}</style>'+report()+'</html>','text/html');}
function updateTests(id){const el=document.getElementById('tests-'+id);if(el)el.outerHTML=testCards(id);}
function refreshConsole(id,focus=false){const el=document.getElementById('console-'+id);if(el){el.innerHTML=consoleHTML(id);el.scrollTop=el.scrollHeight;if(focus)el.querySelector('input')?.focus();}document.querySelectorAll('[data-run]').forEach(b=>b.disabled=Boolean(live));document.querySelectorAll('[data-stop]').forEach(b=>b.disabled=!live);document.querySelectorAll('[data-code]').forEach(e=>e.readOnly=Boolean(live));if(!live){const h=document.getElementById('history-'+id);if(h)h.innerHTML=historyHTML(id);const details=h?.closest('details');if(details)details.querySelector('summary').textContent=txt(B('Previous runs','Larian terdahulu','之前的运行'))+' ('+(state.runs[id]||[]).length+')';}}
function armTimer(){if(!live)return;clearTimeout(live.timer);live.timer=setTimeout(()=>finish('timeout',txt(B('Execution took too long. Check for an endless loop.','Pelaksanaan terlalu lama. Semak gelung tanpa akhir.','执行过久，请检查无限循环。'))),6500);}
function finish(status,error=''){if(!live)return;const job=live;live=null;clearTimeout(job.timer);job.worker?.terminate();job.run.status=status;job.run.error=error;state.runs[job.program]=[...(state.runs[job.program]||[]),job.run].slice(-30);save();refreshConsole(job.program);updateTests(job.program);}
function startRun(id){if(live||!PROGRAMS[id])return;const code=starterCode(id);if(!code.trim())return;state.code[id]=code;cleared.delete(id);save();const run={id:Date.now().toString(36),at:new Date().toISOString(),code,stdout:'',transcript:'',error:'',inputs:[],status:'running'};live={program:id,run,worker:null,pending:null,timer:null};try{const w=new Worker('python-worker.js?v=3');live.worker=w;w.onmessage=({data})=>{if(!live||live.worker!==w)return;if(data.type==='output'){live.run.stdout=(live.run.stdout+String(data.text)).slice(0,18000);live.run.transcript=(live.run.transcript+String(data.text)).slice(0,24000);refreshConsole(id);}else if(data.type==='input'){clearTimeout(live.timer);live.pending={id:data.id,prompt:String(data.prompt).slice(0,1000)};refreshConsole(id,true);}else if(data.type==='done')finish('done');else if(data.type==='error')finish('error',String(data.error));};w.onerror=()=>finish('error',txt(B('Python could not start. Open this lesson through its web link, not as a local file.','Python tidak dapat bermula. Buka pelajaran melalui pautan web, bukan fail tempatan.','Python 无法启动。请通过网页链接打开，而不是直接打开本地文件。')));armTimer();w.postMessage({type:'run',code});refreshConsole(id);}catch{finish('error',txt(B('Unable to start Python. Reload this page through the lesson web link.','Tidak dapat memulakan Python. Muat semula melalui pautan web pelajaran.','无法启动 Python。请通过课程网页链接重新加载。')));}}
function sendInput(form){if(!live?.pending||live.program!==form.dataset.input)return;if(live.run.inputs.length>=40){finish('error','Input limit reached.');return;}const value=form.elements.response.value.slice(0,500),p=live.pending,id=live.program;live.run.inputs.push(value);live.run.transcript=(live.run.transcript+p.prompt+value+'\n').slice(0,24000);live.pending=null;live.worker.postMessage({type:'input',id:p.id,value});armTimer();refreshConsole(id);}
function refreshEditor(el){const id=el.dataset.code;document.getElementById('highlight-'+id).innerHTML=codeMarkup(el.value)+'\n';document.getElementById('gutter-'+id).textContent=el.value.split('\n').map((_,i)=>i+1).join('\n');syncScroll(el);}
function syncScroll(el){const pre=document.getElementById('highlight-'+el.dataset.code),gutter=document.getElementById('gutter-'+el.dataset.code);pre.scrollTop=el.scrollTop;pre.scrollLeft=el.scrollLeft;gutter.scrollTop=el.scrollTop;}
function bindEditors(){document.querySelectorAll('[data-code]').forEach(el=>{el.addEventListener('scroll',()=>syncScroll(el));el.addEventListener('keydown',ev=>{if(ev.key==='Tab'&&!el.readOnly){ev.preventDefault();if(ev.shiftKey){const start=el.selectionStart,lineStart=el.value.lastIndexOf('\n',start-1)+1;if(el.value.slice(lineStart,lineStart+4)==='    '){el.setRangeText('',lineStart,lineStart+4,'start');el.selectionStart=el.selectionEnd=Math.max(lineStart,start-4);}}else el.setRangeText('    ',el.selectionStart,el.selectionEnd,'end');el.dispatchEvent(new Event('input',{bubbles:true}));}else if(ev.key==='Enter'&&(ev.ctrlKey||ev.metaKey)){ev.preventDefault();startRun(el.dataset.code);}else if(ev.key==='Enter'&&!ev.shiftKey&&!el.readOnly){ev.preventDefault();const line=el.value.slice(0,el.selectionStart).split('\n').at(-1),spaces=line.match(/^ */)[0]+(line.trimEnd().endsWith(':')?'    ':'');el.setRangeText('\n'+spaces,el.selectionStart,el.selectionEnd,'end');el.dispatchEvent(new Event('input',{bubbles:true}));}});});}
function setCode(id,code){if(live)finish('stopped');if(Object.hasOwn(state.code,id)&&state.code[id].trim()&&state.code[id]!==code&&!confirm(txt(B('Replace the code in this editor? Download your .py first to keep your edits. Previous runs stay saved.','Ganti kod dalam editor? Muat turun .py dahulu untuk menyimpan suntingan. Larian terdahulu kekal.','替换编辑器中的代码？如需保留修改，请先下载 .py。之前的运行记录会保留。'))))return;state.code[id]=code;save();render();document.getElementById('ide-'+id)?.scrollIntoView({block:'center'});}
function importNotebook(raw){if(raw?.app===APP)return validate(raw);if(raw?.app!=='year9-helpdesk-project'||raw.version!==1)throw Error('Wrong lesson');const s=fresh();s.name=String(raw.answers?.name||'').slice(0,100);s.className=String(raw.answers?.className||'').slice(0,60);s.guided=matchesSupport(s.name);s.lang=['en','ms','zh'].includes(raw.lang)?raw.lang:'en';s.legacy=raw;if(typeof raw.code?.core==='string'&&raw.code.core.length<=20000)s.code.core=raw.code.core;s.runs.core=(raw.runs?.core||[]).slice(-30).map(r=>cleanRun({...r,transcript:r.output,inputs:(r.inputs||[]).map(i=>i.value)})).filter(Boolean);return s;}
function legacyNotebook(){try{const raw=JSON.parse(localStorage.getItem('year9-helpdesk-project'+(teacher?'-teacher':'-student'))||'null');return raw?.app==='year9-helpdesk-project'?raw:null;}catch{return null;}}
const originalWelcome=welcome;
welcome=function(){return originalWelcome().replace('</form>',`${legacyNotebook()?`<button type="button" data-action="legacy">${t('Continue my earlier notebook','Sambung buku nota terdahulu','继续之前的学习记录')}</button>`:''}</form>`);};
function applyImported(imported){if(live)finish('stopped');backup();const targetKey=prefix+'-'+encodeURIComponent(normalize(imported.name)||'preview');if(targetKey!==storageKey){const previous=readSaved(targetKey);if(previous)download('Previous-helpdesk-notebook.json',JSON.stringify(previous,null,2),'application/json');}state=imported;draft={name:state.name,className:state.className};storageKey=targetKey;try{localStorage.setItem(prefix+'-identity',JSON.stringify(draft));}catch{}entry=!state.name;save();render();notice(B('Notebook loaded. A backup of the previous work was downloaded first.','Buku nota dimuatkan. Sandaran kerja terdahulu telah dimuat turun dahulu.','学习记录已加载。替换前已下载原记录备份。'));}
document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.identity){draft[el.dataset.identity]=el.value;return;}if(el.dataset.answer&&answerKeys.has(el.dataset.answer)){state.answers[el.dataset.answer]=el.value.slice(0,6000);delete state.checked[el.dataset.answer];const q=document.getElementById('question-'+el.dataset.answer);if(q){q.querySelector('.question-feedback').innerHTML='';q.querySelectorAll('.choice').forEach(l=>l.classList.toggle('selected',l.querySelector('input').checked));}save();if(/^(start_|now_|phase_)/.test(el.dataset.answer)){const f=document.getElementById('focus-summary');if(f)f.innerHTML=focusSummary(state.page==='pit'?'now':'start');const p=document.getElementById('phase-summary');if(p)p.innerHTML=phaseSummary();}}else if(el.dataset.code&&PROGRAMS[el.dataset.code]){state.code[el.dataset.code]=el.value.slice(0,20000);if(el.value.length>20000)el.value=state.code[el.dataset.code];refreshEditor(el);save();refreshConsole(el.dataset.code);updateTests(el.dataset.code);}});
document.addEventListener('submit',ev=>{if(ev.target.id==='entry-form'){ev.preventDefault();begin();}else if(ev.target.dataset.input){ev.preventDefault();sendInput(ev.target);}});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.hasAttribute('data-lang')){if(live)finish('stopped');state.lang=el.value;save();render();}else if(el.hasAttribute('data-compare')){state.compare=el.checked;save();if(live)finish('stopped');render();}else if(el.hasAttribute('data-restore')){const file=el.files[0];if(!file)return;try{if(file.size>8000000)throw Error('Large');const imported=importNotebook(JSON.parse(await file.text()));applyImported(imported);}catch{notice(B('This is not a valid helpdesk notebook. Your work was kept.','Ini bukan buku nota meja bantuan yang sah. Kerja anda dikekalkan.','这不是有效的服务台学习记录。你的作品已保留。'));}}});
document.addEventListener('click',ev=>{const home=ev.target.closest('[data-home]');if(home){ev.preventDefault();if(live)finish('stopped');draft={name:state.name,className:state.className};entry=true;render();return;}const b=ev.target.closest('button');if(!b||b.disabled)return;if(b.dataset.page){go(b.dataset.page);return;}if(b.dataset.exercise){if(live)finish('stopped');state.tabs[state.page]=b.dataset.exercise;save();render();document.querySelector('.exercise-tabs')?.scrollIntoView({block:'start'});return;}if(b.dataset.check){const q=questions.find(x=>x.id===b.dataset.check);if(!q||!val(q.id)){notice(B('Choose an answer first.','Pilih jawapan dahulu.','请先选择答案。'));return;}if(state.first[q.id]===undefined)state.first[q.id]=val(q.id);state.checked[q.id]=true;save();document.getElementById('question-'+q.id).outerHTML=mcq(q);return;}if(b.dataset.move){const id=b.dataset.move,p=PARSONS[id];if(!p)return;const o=[...order(id)],i=Number(b.dataset.pos),j=i+Number(b.dataset.dir);if(j<0||j>=o.length)return;[o[i],o[j]]=[o[j],o[i]];state.orders[id]=o;delete state.orderChecked[id];save();document.getElementById('puzzle-'+id).outerHTML=puzzleHTML(id);document.querySelector(`[data-move="${id}"][data-pos="${j}"]:not(:disabled)`)?.focus();return;}if(b.dataset.orderCheck){const id=b.dataset.orderCheck;if(!PARSONS[id])return;state.orders[id]=[...order(id)];state.orderChecked[id]=true;save();document.getElementById('puzzle-'+id).outerHTML=puzzleHTML(id);return;}if(b.dataset.run){startRun(b.dataset.run);return;}if(b.hasAttribute('data-stop')){finish('stopped');return;}if(b.dataset.download){download((b.dataset.download==='core'?'helpdesk':b.dataset.download)+'.py',starterCode(b.dataset.download),'text/x-python');return;}if(b.dataset.clear){if(live?.program===b.dataset.clear){notice(B('Stop the program before clearing the console.','Hentikan atur cara sebelum mengosongkan konsol.','请先停止程序，再清空控制台。'));return;}cleared.add(b.dataset.clear);refreshConsole(b.dataset.clear);return;}if(b.dataset.expand){expanded=expanded===b.dataset.expand?null:b.dataset.expand;document.getElementById('ide-'+b.dataset.expand).classList.toggle('expanded',Boolean(expanded));return;}if(b.dataset.starter){const p=PROGRAMS[b.dataset.starter];setCode(p.id,state.guided?p.guided:p.starter);return;}if(b.hasAttribute('data-copy-core')){setCode('extension',starterCode('core'));return;}if(b.hasAttribute('data-assemble')){const required=['p_calc1','p_calc2','p_if1'];if(!required.every(id=>ordered(id)&&state.orderChecked[id])){notice(B('First check both calculation puzzles and decision puzzle 1. You can also write your own code directly.','Semak kedua-dua teka-teki pengiraan dan teka-teki keputusan 1 dahulu. Anda juga boleh menulis kod sendiri.','请先检查两道计算排序题和判断排序题 1。也可以直接自己编写代码。'));return;}const code=[PARSONS.p_calc1.blocks[0],'minutes_available = int(input("Minutes available: "))',PARSONS.p_calc1.blocks[1],PARSONS.p_calc2.blocks[2],'print("Estimated wait:", waiting_minutes, "minutes")','print("Estimated total:", total_minutes, "minutes")',...order('p_if1').map(n=>PARSONS.p_if1.blocks[n])].join('\n')+'\n';setCode('core',code);return;}if(b.dataset.tutor||b.dataset.tutorCase){if(b.dataset.tutorCase){tutorCase=Number(b.dataset.tutorCase);state.tutor=0;}else state.tutor=b.dataset.tutor==='-1'?Math.max(0,state.tutor-1):(state.tutor+1)%9;save();document.getElementById('tutor').outerHTML=tutor();return;}switch(b.dataset.action){case'home':if(live)finish('stopped');draft={name:state.name,className:state.className};entry=true;render();window.scrollTo(0,0);break;case'preview-route':if(live)finish('stopped');save();{const guided=!state.guided;storageKey=prefix+(guided?'-guided-preview':'-preview');state=readSaved(storageKey)||fresh();state.guided=guided;entry=false;save();render();}break;case'pdf':printable();break;case'backup':backup();break;case'report':readable();break;case'legacy':try{applyImported(importNotebook(legacyNotebook()));}catch{notice(B('No earlier notebook found.','Tiada buku nota terdahulu.','未找到之前的学习记录。'));}break;}});
window.addEventListener('pagehide',()=>{if(live)finish('stopped');save();});
// Initial render is called by lesson.js after the Week 5 views load.
window.matchMedia?.('(min-width: 851px)').addEventListener('change',ev=>{document.querySelectorAll('.lesson-menu,.sidebar-aims').forEach(el=>el.open=ev.matches);});
